#!/usr/bin/env python3
"""Write SPEC.md from preview_data.json / cutlist.csv / fit_check.json (run after frame.py and check_fit.py)."""
import csv
import json
import os

d = os.path.dirname(os.path.abspath(__file__))
P = json.load(open(os.path.join(d, "preview_data.json")))
S = P["summary"]
E = S["engine"]
cut = {r[0]: r for r in list(csv.reader(open(os.path.join(d, "cutlist.csv"))))[1:]}
fit = json.load(open(os.path.join(d, "fit_check.json"))) if os.path.exists(os.path.join(d, "fit_check.json")) else None
eng_res = os.path.join(d, "..", "engine-design", "results.json")
eres = json.load(open(eng_res)) if os.path.exists(eng_res) else None
w = lambda n: "%s" % format(round(n), ",")

L = []
a = L.append
a("# Truss chassis for the 349cc liquid-cooled single\n")
a("Minimal triangulated space frame, every joint a truss node, **fitted to the real engine** from `../engine-design` (349 cc, 4 valves, 15,000 rpm design). "
  "Generated by `frame.py`; all numbers below come from it.\n")
a("Axes: x forward, y left, z up, origin = swingarm pivot centre, millimetres. (The engine uses the same axis directions with its own origin on the crank axis.)\n")
a("## 1. Targets and geometry\n")
a("| Item | Value |\n|---|---|")
env = E["envelope_mm"]
for k, v in [("Wheelbase", "1400 mm (front axle x = 840, rear axle x = -560)"), ("Wheels", "17 in front and rear (R about 300 mm)"),
             ("Rake / trail", "25 deg / about 107 mm (fork offset 30 mm)"), ("Swingarm length", "560 mm"),
             ("Seat height", "800 mm above ground (neutral ergonomic, rider 170-180 cm)"),
             ("Hip point / footpeg / grips", "(-60, 540) / (300, 10) / (520, 680), side view x,z; hip to grips about 600 mm, hip to peg about 640 mm"),
             ("Engine crank axis", "x %g, y %g, z %g (same height as the wheel axles)" % tuple(E["origin_mm"])),
             ("Engine envelope in the bike", "x %s..%s, y %s..%s, z %s..%s mm" % (w(env["x"][0]), w(env["x"][1]), w(env["y"][0]), w(env["y"][1]), w(env["z"][0]), w(env["z"][1]))),
             ("Frame extent", "%s x %s x %s mm" % (w(S["extent_mm"]["x"][1] - S["extent_mm"]["x"][0]), w(S["extent_mm"]["y"][1] - S["extent_mm"]["y"][0]), w(S["extent_mm"]["z"][1] - S["extent_mm"]["z"][0])))]:
    a("| %s | %s |" % (k, v))
a("\nFor comparison, the Triumph Scrambler 900 is seat 790, wheelbase 1445, rake 25.6 deg, trail 109, 19/17 in wheels. This frame is a neutral naked-bike posture, not scrambler-style.\n")
a("## 2. Truss rules used\n")
a("- Straight tubes only. Member centrelines meet at one point at every node, so members carry axial load only.")
a("- Rank of the rigidity matrix is %d for %d nodes (3j - 6 = %d): **isostatic, %d members, none redundant**. Removing any member would make a mechanism." % (S["rigidity_rank"], S["nodes"], S["isostatic_count"], S["members"]))
a("- Seat (nodes C, S), tank (S, HT), footpegs (P), shock (M), swingarm pivot (D) and engine (E, F) all attach at nodes, never mid-span.")
a("- No tube enters the engine: nearest tube surface to an engine clearance box is %s mm (requirement 10 mm). No two tubes cross: nearest tube-to-tube gap between members that do not share a node is %s mm." % (S["min_gap_to_engine_mm"], S["min_tube_to_tube_gap_mm"]))
a("- The volume above the engine (x %g..%g, y +-%g, z %g..%g) is kept free of tubes for the airbox, injector, ECU and wiring; nearest tube is %s mm away." % (
    S["airbox_zone_mm"]["x"][0], S["airbox_zone_mm"]["x"][1], S["airbox_zone_mm"]["y"][1], S["airbox_zone_mm"]["z"][0], S["airbox_zone_mm"]["z"][1], S["min_gap_to_airbox_zone_mm"]))
a("- The steering head tube (HT-HB, 50 x 3 mm) is the one non-truss element: it is a rigid link between two nodes.\n")

a("## 3. How the engine fits\n")
a("The engine is the single-cylinder 349 cc design (%.1f kg dry, %.1f kg with oil and coolant). It sits with its crank axis at the height of the wheel axles. "
  "The cylinder is vertical, the exhaust leaves the front of the head and the intake enters the rear, as in the engine design." % (eres["mass"]["dry_kg"] if eres else 26.9, E["wet_kg"]))
a("")
a("- **Mounts.** The engine has two ear pairs: front-upper at engine x = 83, z = 163 and rear-upper at x = -125, z = 78, both with 14 mm holes through ears at |y| 62..82. "
  "In the bike these are nodes **E** (%g, +-%g, %g) and **F** (%g, +-%g, %g)." % (P["engine"]["mounts"]["E"][0], E["mount_y_mm"], P["engine"]["mounts"]["E"][1], P["engine"]["mounts"]["F"][0], E["mount_y_mm"], P["engine"]["mounts"]["F"][1]))
a("- **Joint at each of the four mounts:** one M12 bolt (about M12 x 90) goes through the engine ear, a 24/13 mm spacer tube (about 49 mm long, `SPACER_*` in `frame.step`), the 6 mm frame lug plate (hole 13 mm) and a lock nut. "
  "The spacers exist because the alternator cover bulges to 126 mm from the centreline on the bike's right and the tubes must clear it by 10 mm, so the frame nodes sit at |y| = %g mm." % E["mount_y_mm"])
a("- **Load share.** The engine's centre of gravity is %.0f%% of the way from the rear mounts to the front mounts, so the front mounts carry %.0f%% of the engine's weight: %.1f kg on each E node and %.1f kg on each F node (F also carries half of the 20 kg drivetrain allowance, see section 6)." % (E["front_share"] * 100, E["front_share"] * 100, E["kg_on_each_E"], E["kg_on_each_F"]))
a("- **Engine sides.** The alternator and its cover are on the bike's **right** (-y). The output flange (crank end, for a sprocket, clutch or CVT later) and the water and oil pump cover are on the bike's **left** (+y), which is where a chain drive normally goes. The left footpeg (P at y = 235) is 130 mm outboard of the flange.")
a("- **Space left for the drivetrain.** The rear of the engine covers is at x = %s. The clutch and gearbox or CVT go in the pocket between the engine and the pivot tube (x = 0): about 125 mm long (x 25 to %s) and about 280 mm wide between the frame tubes. The M-F bars pass above it (z above 100 mm for x up to 150). That is tight for a six-speed box: if it does not fit, move `ENGINE_ORIGIN` forward in `frame.py` (the front tyre limits it, see the next point) or move the pivot back." % (w(env["x"][0]), w(env["x"][0])))
a("- **Front tyre.** The oil filter is the most forward engine part, at x = %s. With the fork extended the front tyre's rear edge is about 84 mm ahead of it. Fork travel moves the tyre back by about 0.42 mm for every mm of compression (25 deg rake), so the fork is not modelled here but about 120 mm of travel would take most of that gap." % w(env["x"][1]))
a("- **What was dropped.** The earlier layout used cross tubes E-E and F-F plus diagonals S-E across the middle. With the real engine they would cut through the cylinder head (E-E at z = 143 passes through the front mounting ears and the exhaust port area), and the old E-D would pass 8 mm from node F, which makes E-F-D almost a straight line and leaves F barely held. "
  "Those bars were removed and the 39-bar set re-chosen: an annealing search over every bar that clears the engine and the airbox zone, does not cross another bar and passes at least 25 mm from every other node, scored on tube mass after sizing, stiffness and safety factors under the real load cases. "
  "Four runs from different random starts converged to the same set (`topology_search.py`). The engine now hangs from the top rail through the two hangers S-E and S-F instead of sitting on cross tubes.")
if fit:
    a("")
    a("**Check against the real engine solids** (`check_fit.py`, writes `fit_check.json`): the engine STEP was moved to the crank-axis position and measured against every frame solid with exact B-rep distances. "
      "Largest amount any engine vertex stuck out of the clearance boxes used by the solver: %s mm (%s). Closest frame part: %s at %s mm; the four mount spacers touch the ear faces by design%s. Nearest tube or plate to a real engine part: %s." % (
          fit["max_protrusion_outside_boxes_mm"], "boxes enclose the engine" if fit["boxes_enclose_engine"] else "BOXES TOO SMALL, fix before use",
          fit["closest_frame_part"], fit["min_gap_frame_to_engine_mm"], (", overlap volumes: %s" % fit["overlaps_mm3"]) if fit.get("overlaps_mm3") else " and nothing overlaps",
          ", ".join("%s %s mm" % (n, g) for n, g in [x for x in fit["closest_list"] if not x[0].startswith("SPACER_")][:3])))
a("")
a("## 4. Nodes (mm)\n")
a("| Node | x | y | z | Role |\n|---|---|---|---|---|")
role = {"HT": "head tube top", "HB": "head tube bottom", "M": "shock top (centreline)", "C": "seat rear", "S": "seat front / tank", "D": "swingarm pivot", "E": "engine front-upper mount", "F": "engine rear-upper mount", "P": "footpeg"}
for n, p in P["nodes"].items():
    a("| %s | %s | %s | %s | %s |" % (n, w(p[0]), w(p[1]), w(p[2]), role.get(n[0] if n not in ("HT", "HB") else n, "")))
a("")
a("## 5. Members and results\n")
a("Tube sizes: **S** = 19 x 1.6 mm, **M** = 28 x 2 mm (pivot tube only), **H** = 50 x 3 mm head tube. Mild-steel ERW, yield taken as 250 MPa, E = 210 GPa. Forces in N, tension positive. SF = safety factor (target 2.0).\n")
a("| Member | Tube | Centreline mm | Cut mm | Static 1 g | Bump 3 g | Brake 1 g | SF yield | SF buckle |\n|---|---|---|---|---|---|---|---|---|")
for m in P["members"]:
    f = m["forces"]
    sb = "tension" if m["sf_buckle"] is None else (">100" if m["sf_buckle"] > 100 else "%.1f" % m["sf_buckle"])
    a("| %s | %s | %s | %s | %s | %s | %s | %.1f | %s |" % (m["id"], m["size"], w(m["len"]), w(float(cut[m["id"]][3])), w(f["static"]), w(f["bump_3g"]), w(f["brake_1g"]), m["sf_yield"], sb))
a("")
a("## 6. Load cases and method\n")
a("Pin-jointed 3D truss, stiffness method (numpy). Sprung mass %.0f kg: rider 90, misc 30, tank/fuel 20, engine with oil, coolant and extras %.1f kg (%.1f wet + %.0f for exhaust, radiator, ECU and wiring), "
  "a **20 kg allowance for the clutch and gearbox or CVT that are not designed yet** (hung on the rear mounts), plus %.1f kg of tube. Supports only remove rigid-body motion; reactions come out as 0.0 N, which confirms each case is self-equilibrated.\n"
  % (S["cases"]["static"]["total_mass_kg"], E["wet_kg"] + E["extras_kg"], E["wet_kg"], E["extras_kg"], S["tube_mass_kg"]))
a("| Case | Front wheel N | Rear wheel N | Shock axial N | Max node movement mm |\n|---|---|---|---|---|")
for c, nm in (("static", "Static 1 g"), ("bump_3g", "Bump 3 g (vertical)"), ("brake_1g", "Braking 1 g")):
    a("| %s | %s | %s | %s | %.2f |" % (nm, w(S["cases"][c]["R_front_N"]), w(S["cases"][c]["R_rear_N"]), w(S["cases"][c]["shock_axial_N"]), S["u_max_mm"][c]))
a("\nFront wheel load enters the head bearings (HT, HB) through the fork. Rear wheel load enters through the shock (node M) and the swingarm pivot (D), from the swingarm moment balance (shock lower mount x = -300).\n")
a("Result: minimum yield safety factor **%.2f**, minimum buckling safety factor **%.2f**, no failing members. Total tube mass **%.1f kg**; the placeholder-engine layout was 9.8 kg. "
  "Node movement at the 3 g bump is %.1f mm, up from 0.6 mm in the placeholder layout because the E-E and F-F cross tubes are gone; still small, but the frame is a softer structure than before." % (S["min_sf_yield"], S["min_sf_buckle"], S["tube_mass_kg"], S["u_max_mm"]["bump_3g"]))
a("Cornering is not a separate case: at 1 g lateral the bike leans about 45 deg and the frame sees roughly a 1.4 g vertical load, which the 3 g bump case covers for axial forces. Lateral kicks and torsion are not analysed.\n")
if eres:
    bal = eres["balance"]
    a("**Engine shake is not in these cases.** The engine is treated as a dead weight. In real running the single cylinder shakes the frame: at 15,000 rpm the engine design leaves about %.1f tonnes-force of shaking after counterweights and the balance shaft, almost all of it at twice engine speed (%.0f Hz), which one balance shaft cannot cancel. "
      "Bolting the engine rigidly to a thin-tube truss at that level is likely to fatigue tubes and welds near E and F (fatigue is not analysed here). Either put rubber bushes in the mounts (the spacers allow it) or limit the first runs to low rpm and inspect the nodes. This is the biggest open risk in the frame.\n" % (bal["peak_with"] / 9806.65, 2 * 15000 / 60.0))
a("## 7. Fabrication (cheapest route)\n")
a("- Total tube: 19 x 1.6 mm %s mm, 28 x 2 mm %s mm, 50 x 3 mm head tube %s mm. Tube mass %.1f kg." % (w(S["tube_length_mm"]["S"]), w(S["tube_length_mm"]["M"]), w(S["tube_length_mm"]["H"]), S["tube_mass_kg"]))
a("- `cutlist.csv` lists each member's centreline length, the cut length (axis pierce to pierce) and the included angle and mating tube at each end. Cope (fishmouth) each end onto the mating tube, trim to fit.")
a("- Plates, 6 mm mild steel, flat patterns in `frame.dxf`: engine lug 70 x 90, hole 13 (x8, four per side: E and F); swingarm pivot plate 110 x 150, hole 20 (x2); footpeg plate 50 x 60, hole 10 (x2); shock plate 60 x 80, hole 12 (x1). Also 4 spacer tubes 24 x 5.5 mm, about 49 mm long, and 4 M12 x 90 bolts with lock nuts. A local laser or CNC shop is fine; JLCCNC can cut the plates too. JLCCNC is not a tube-frame service.")
a("- Order: tack the two head nodes and the pivot tube in a flat jig first, then build each side, then the cross tubes (D-D, C-C) and the M node, then weld out. Hang the real engine (or a wooden template of it) from the E and F plates **before** final welding so the plates line up with the ears. Check diagonals and the node positions against `frame.step` first.")
a("- Rough cost guess, not sourced: tube about 10 kg of steel, plates a few hundred rupees, welding and jig the main cost; plan roughly Rs 8,000 to 20,000 at a local workshop.\n")
a("## 8. Limits and what to change\n")
a("- Idealised pin joints. Welded joints add some bending stiffness and some secondary bending; neither is modelled.")
a("- Lateral loads, torsion, fatigue, weld quality, chain/drive loads, engine shake and crash loads are not analysed.")
a("- The 20 kg drivetrain allowance and the 9 kg of engine extras are guesses. Replace them with real numbers when the exhaust and the gearbox or CVT exist.")
a("- To move the engine, edit `ENGINE_ORIGIN` (or `MOUNT_Y`) in `frame.py` and rerun. The rigidity, safety factors and clearances are re-checked; if the bar set stops being rigid or a bar hits the engine, run `topology_search.py` and paste the new member list into `base_members()`.")
a("- **This is not a certified motorcycle frame.** A frame that carries a rider needs real FEA and physical testing by a qualified person before anyone rides it.\n")
a("## 9. Files\n")
a("| File | Content |\n|---|---|")
for f, t in [("frame.py", "parametric generator, solver and exporter (reads ../engine-design/interface.json)"),
             ("frame.step", "39 tubes, 9 plates, 4 mount spacers and the engine clearance boxes as named parts. The real engine is `../engine-design/engine.step` moved by (300, 0, -20) mm"),
             ("frame.dxf", "side, top, front wireframes with the engine clearance boxes, and plate flat patterns (mm)"),
             ("cutlist.csv", "tube cut list"), ("preview.html / preview.template.html", "3D viewer with the real engine (`build_preview.py` injects `preview_data.json` and the engine meshes)"),
             ("check_fit.py, fit_check.json", "solid-to-solid check of the frame against the engine STEP"),
             ("topology_search.py", "annealing search that chose the 39-bar set"),
             ("results.json, preview_data.json", "solver output"), ("gen_spec.py", "writes this file")]:
    a("| `%s` | %s |" % (f, t))
a("\nRegenerate: `python frame.py && python check_fit.py && python build_preview.py && python gen_spec.py` (needs numpy, cadquery, ezdxf; run `../engine-design/build.py` first).")
open(os.path.join(d, "SPEC.md"), "w").write("\n".join(L) + "\n")
print("SPEC.md written", len(L), "lines")
